#!/usr/bin/env bash
set -euo pipefail
source /c/Users/mikes/WebstormProjects/scaffold/tmp/pass/pass-env.sh
label=${1-}; output="$SCR/$label"; campaign=.orkestrel/campaign/docs-parity; prompt=prompt.txt; verdict="$SCAFFOLD/$campaign/d7n-guide-upload-handoff-verdict.md"; parse="$SCR/d7n-guide-upload-prompt-parse"; guide="$FLEET/guide"; close="$SCR/d7n-guide-registry-close"; prepublish="$SCR/d7n-guide-registry-native-prepublish"; pack="$SCR/packed/d7n-guide-registry-native-pack"; archive="$pack/orkestrel-guide-0.0.18.tgz"; digest=01e460ee05cb84b4d24ffc2418aad29ca196d4152cf49b03bf0b68637858c638; scaffold_pack="$SCR/packed/d7n-scaffold-upper-git-final-pack"
fail(){ printf '%s\n' "$1" >&2; exit 1; }
run(){ local name="$1"; shift; local status=0; if timeout --kill-after=15s 120s "$@" > "$output/$name.stdout.txt" 2> "$output/$name.stderr.txt"; then status=0; else status=$?; fi; printf '%s\n' "$status" > "$output/$name.exit.txt"; return "$status"; }
[[ "$label" =~ ^[a-z][a-z0-9-]*$ ]] || fail 'record label is required'; test ! -e "$output" || fail 'checkpoint evidence exists'; test "$(tr -d '\r\357\273\277' < "$parse/parse.exit.txt")" = 0 || fail 'Guide prompt parser receipt differs'; test -f "$verdict" || fail 'Guide upload verdict is absent'; grep -Fx 'VERDICT: PASS' "$verdict" > /dev/null || fail 'Guide upload verdict does not pass'; test -f "$SCAFFOLD/$prompt" || fail 'Scaffold prompt is absent'; test "$(node "$SCR/read-package-field.mjs" "$SCAFFOLD/package.json" version)" = 0.0.64 || fail 'Scaffold version differs'; test "$(<"$prepublish/action.exit.txt")" = 0 || fail 'Guide prepublish receipt differs'; test -f "$close/release-head.txt" || fail 'Guide closure receipt is absent'; test -f "$archive" || fail 'Guide archive is absent'
mkdir "$output"; run scaffold-branch git -C "$SCAFFOLD" branch --show-current; test "$(<"$output/scaffold-branch.stdout.txt")" = main || fail 'Scaffold is not on main'; run scaffold-index git -C "$SCAFFOLD" diff --cached --quiet; test "$(<"$output/scaffold-index.exit.txt")" = 0 || fail 'Scaffold index is not empty'; run prompt-directory grep -F "cd 'C:/Users/mikes/WebstormProjects/guide'" "$SCAFFOLD/$prompt"; test "$(<"$output/prompt-directory.exit.txt")" = 0 || fail 'Guide directory is absent from prompt'; run prompt-publish grep -F 'npm publish --ignore-scripts --browser=false' "$SCAFFOLD/$prompt"; test "$(<"$output/prompt-publish.exit.txt")" = 0 || fail 'Guide publish command is absent'; mapfile -t directories < <(grep -oE 'C:/Users/mikes/WebstormProjects/[^ '\'';)]+' "$SCAFFOLD/$prompt"); for directory in "${directories[@]}"; do test "$directory" = C:/Users/mikes/WebstormProjects/guide || fail "prompt names sibling upload directory: $directory"; done
run guide-branch git -C "$guide" branch --show-current; test "$(<"$output/guide-branch.stdout.txt")" = main || fail 'Guide is not on main'; run guide-head git -C "$guide" rev-parse HEAD; test "$(<"$output/guide-head.stdout.txt")" = "$(<"$close/release-head.txt")" || fail 'Guide HEAD differs from closure'; run guide-origin git -C "$guide" rev-parse origin/main; test "$(<"$output/guide-origin.stdout.txt")" = "$(<"$close/release-head.txt")" || fail 'Guide origin main differs from closure'; run guide-status git -C "$guide" status --porcelain=v1 --untracked-files=all; test ! -s "$output/guide-status.stdout.txt" || fail 'Guide is not clean'; run guide-manifest cmp "$pack/extract/package/package.json" "$guide/package.json"; run guide-dist diff -r "$pack/extract/package/dist" "$guide/dist"; run guide-sha sha256sum "$archive"; run guide-digest awk -v expected="$digest" '$1 == expected { found = 1 } END { exit found ? 0 : 1 }' "$output/guide-sha.stdout.txt"; test "$(<"$output/guide-digest.exit.txt")" = 0 || fail 'Guide archive digest differs'; run scaffold-manifest cmp "$scaffold_pack/extract/package/package.json" "$SCAFFOLD/package.json"; run scaffold-dist diff -r "$scaffold_pack/extract/package/dist" "$SCAFFOLD/dist"
run status-before git -C "$SCAFFOLD" status --porcelain=v1 --untracked-files=all; while IFS= read -r entry; do path="${entry:3}"; case "$path" in "$prompt"|"$campaign"/*) ;; *) fail "unrelated change: $path";; esac; done < "$output/status-before.stdout.txt"; run fetch git -C "$SCAFFOLD" fetch origin; run ancestry git -C "$SCAFFOLD" merge-base --is-ancestor origin/main HEAD; run check git -C "$SCAFFOLD" diff --check; run add git -C "$SCAFFOLD" add -- "$campaign" "$prompt"; run commit git -C "$SCAFFOLD" -c user.name=Claude -c user.email=noreply@anthropic.com commit -m "Record Guide upload handoff: $label" -m 'Co-Authored-By: Claude <noreply@anthropic.com>' -m 'Claude-Session: codex:01a0810d-21bf-7f60-8534-488348e05743'; run push git -C "$SCAFFOLD" push origin HEAD:main HEAD:claude/orkestrel-npm-audit-deps-14ibta HEAD:claude/docs-parity-windows-01a0810d; run head-after git -C "$SCAFFOLD" rev-parse HEAD; current="$(<"$output/head-after.stdout.txt")"; for pair in 'origin-main origin/main' 'origin-campaign origin/claude/orkestrel-npm-audit-deps-14ibta' 'origin-docs origin/claude/docs-parity-windows-01a0810d'; do set -- $pair; run "$1" git -C "$SCAFFOLD" rev-parse "$2"; test "$(<"$output/$1.stdout.txt")" = "$current" || fail "Scaffold ref differs: $1"; done; run guide-final-branch git -C "$guide" branch --show-current; test "$(<"$output/guide-final-branch.stdout.txt")" = main || fail 'Guide final branch differs'; run guide-final-head git -C "$guide" rev-parse HEAD; test "$(<"$output/guide-final-head.stdout.txt")" = "$(<"$close/release-head.txt")" || fail 'Guide final HEAD differs from closure'; run guide-final-origin git -C "$guide" rev-parse origin/main; test "$(<"$output/guide-final-origin.stdout.txt")" = "$(<"$close/release-head.txt")" || fail 'Guide final origin main differs from closure'; run guide-final-status git -C "$guide" status --porcelain=v1 --untracked-files=all; test ! -s "$output/guide-final-status.stdout.txt" || fail 'Guide final state is not clean'; run guide-final-manifest cmp "$pack/extract/package/package.json" "$guide/package.json"; test "$(<"$output/guide-final-manifest.exit.txt")" = 0 || fail 'Guide final manifest differs from the packed artifact'; run guide-final-dist diff -r "$pack/extract/package/dist" "$guide/dist"; test "$(<"$output/guide-final-dist.exit.txt")" = 0 || fail 'Guide final distribution differs from the packed artifact'; run scaffold-final-manifest cmp "$scaffold_pack/extract/package/package.json" "$SCAFFOLD/package.json"; run scaffold-final-dist diff -r "$scaffold_pack/extract/package/dist" "$SCAFFOLD/dist"; run scaffold-final-branch git -C "$SCAFFOLD" branch --show-current; test "$(<"$output/scaffold-final-branch.stdout.txt")" = main || fail 'Scaffold final branch differs'; run scaffold-final-status git -C "$SCAFFOLD" status --porcelain=v1 --untracked-files=all; test ! -s "$output/scaffold-final-status.stdout.txt" || fail 'Scaffold is not clean'; printf '%s\n' "$output"
